mapper.select:
SELECT sp.sales_point_id, sp.sales_point_code, sp.sales_point_name FROM sales_point sp WHERE sp.sales_point_id IN
#{salesPointId}
AND sp.active_yn = 'Y' AND sp.is_deleted = 0 ORDER BY sp.sales_point_id

SELECT scp.sku_channel_price_id, scp.sales_point_id, scp.selling_price, scp.minimum_selling_price, scp.actual_price, scp.payment_fee, scp.logistics_cost FROM sku_channel_price scp WHERE scp.sku_id = #{skuId} AND scp.sales_point_id IN
#{salesPointId}
AND scp.is_deleted = 0 AND scp.effective_from <= #{asOfDate} AND (scp.effective_to IS NULL OR scp.effective_to >= #{asOfDate}) ORDER BY scp.sales_point_id, scp.effective_from DESC, scp.sku_channel_price_id DESC

SELECT spw.sales_point_warehouse_id, spw.sales_point_id, spw.warehouse_id, spw.priority_no, spw.base_delivery_cost FROM sales_point_warehouse spw INNER JOIN warehouse w ON w.warehouse_id = spw.warehouse_id AND w.active_yn = 'Y' AND w.is_deleted = 0 WHERE spw.sales_point_id IN
#{salesPointId}
AND spw.active_yn = 'Y' AND spw.is_deleted = 0 ORDER BY spw.sales_point_id, CASE WHEN spw.priority_no IS NULL THEN 1 ELSE 0 END, spw.priority_no, spw.sales_point_warehouse_id

SELECT itr.transfer_route_id, itr.source_warehouse_id, itr.source_sales_point_id, itr.destination_warehouse_id, itr.destination_sales_point_id, itr.distance_km, itr.distance_source, itr.distance_route_option, itr.distance_calculated_at FROM inventory_transfer_route itr WHERE itr.active_yn = 'Y' AND itr.is_deleted = 0
OR itr.source_warehouse_id IN
#{warehouseId}
OR itr.source_sales_point_id IN
#{salesPointId}
OR itr.destination_warehouse_id IN
#{warehouseId}
OR itr.destination_sales_point_id IN
#{salesPointId}
ORDER BY itr.transfer_route_id
